import{_ as a,o,c as l,a2 as i}from"./chunks/framework.QCr1ZR1X.js";const p=JSON.parse('{"title":"第6章 工业互联网APP（教师用书）","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch6/教师用书-第6章-工业互联网APP.md","filePath":"teacher/ch6/教师用书-第6章-工业互联网APP.md","lastUpdated":1786967935000}'),r={name:"teacher/ch6/教师用书-第6章-工业互联网APP.md"};function d(n,t,e,s,h,u){return o(),l("div",null,[...t[0]||(t[0]=[i(`<h1 id="第6章-工业互联网app-教师用书" tabindex="-1">第6章 工业互联网APP（教师用书） <a class="header-anchor" href="#第6章-工业互联网app-教师用书" aria-label="Permalink to &quot;第6章 工业互联网APP（教师用书）&quot;">​</a></h1><blockquote><p><strong>本章定位</strong>：从平台到应用——前五章完成了工业互联网的&quot;底层&quot;和&quot;中层&quot;（设备连接、边缘处理、平台管理），本章走完&quot;最后一公里&quot;：把数据变成人看得见、用得上的界面。学生将用已熟悉的Node-RED，给它加上Dashboard&quot;界面&quot;能力，亲手开发一个完整的产线设备监控看板。 <strong>课时安排</strong>：8课时（理论3 + 实践5） <strong>学情分析</strong>：学生已经熟悉Node-RED的基本操作（Modbus通信、Function节点、Switch节点等），这一章加入Dashboard节点，视觉反馈强烈，容易有成就感；但要注意引导学生注重细节（数据准确、布局合理、配色清晰），不能只追求花哨。本章理论部分（6.1-6.3）概念密度较高，需要用类比和案例帮助学生建立直观理解。</p></blockquote><hr><h2 id="一、本章教学目标" tabindex="-1">一、本章教学目标 <a class="header-anchor" href="#一、本章教学目标" aria-label="Permalink to &quot;一、本章教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>理解工业互联网APP的定义、特点和分类</li><li>理解工业APP与传统工业软件的核心差异（小而精 vs 大而全）</li><li>了解五类工业APP（监控/诊断/预测/操作辅助/管理决策）</li><li>了解低代码开发的概念和优势，理解&quot;公民开发者&quot;概念</li><li>熟悉Node-RED Dashboard节点的六种常用组件（Gauge/Chart/Button/Text/Notification/LED）</li><li>理解Tab→Group→Widget三级布局系统</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能安装Node-RED Dashboard节点（注意deprecated问题）</li><li>能逐一配置和使用六种Dashboard节点</li><li>能用Dashboard节点搭建完整的监控看板</li><li>能实现仪表盘、图表、指示灯等常见组件</li><li>能设计合理的看板布局和配色</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ul><li><strong>用户导向思维</strong>：从用户需求出发设计APP，让工人一眼看懂</li><li><strong>工匠精神</strong>：注重看板细节，追求准确、可靠、美观和易用</li><li><strong>创新思维</strong>：发挥想象力设计更多功能</li><li><strong>工程师伦理</strong>：确保APP数据准确、可靠，关注工业APP安全</li></ul><hr><h2 id="二、课时分配与教学安排" tabindex="-1">二、课时分配与教学安排 <a class="header-anchor" href="#二、课时分配与教学安排" aria-label="Permalink to &quot;二、课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>课时</th><th>内容</th><th>教学类型</th><th>重点/难点</th></tr></thead><tbody><tr><td>第1次课</td><td>2h</td><td>6.1 两种APP同一个逻辑 + 6.2 工业APP详解</td><td>理论</td><td><strong>重点</strong>：工业APP vs 传统工业软件的核心差异、五类APP分类；<strong>难点</strong>：理解&quot;小而精&quot;的开发理念</td></tr><tr><td>第2次课</td><td>2h</td><td>6.3 低代码概念 + 6.4 安装Dashboard与节点上手（前半）</td><td>理论+实践</td><td><strong>重点</strong>：低代码理念、公民开发者概念、Gauge/Chart配置；<strong>难点</strong>：Chart节点多线显示（topic字段）</td></tr><tr><td>第3次课</td><td>2h</td><td>6.4 节点上手（后半）+ 布局系统</td><td>实践</td><td><strong>重点</strong>：Button/Text/Notification/LED配置、Tab→Group→Widget三级布局；<strong>难点</strong>：LED颜色规则配置、Notification条件触发</td></tr><tr><td>第4次课</td><td>2h</td><td>6.5 综合实践：开发完整产线监控Dashboard</td><td>实践</td><td><strong>重点</strong>：完整流程整合、多输出Function节点；<strong>难点</strong>：连线总览的理解与排查、Switch+Notification条件告警</td></tr></tbody></table><hr><h2 id="三、各节教学实施建议" tabindex="-1">三、各节教学实施建议 <a class="header-anchor" href="#三、各节教学实施建议" aria-label="Permalink to &quot;三、各节教学实施建议&quot;">​</a></h2><h3 id="_6-1-两种app-同一个逻辑-理论" tabindex="-1">6.1 两种APP，同一个逻辑（理论） <a class="header-anchor" href="#_6-1-两种app-同一个逻辑-理论" aria-label="Permalink to &quot;6.1 两种APP，同一个逻辑（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>互动提问</strong>：&quot;你们手机上装了多少个APP？微信、淘宝、抖音——它们来自不同公司，但都能在同一台手机上运行，为什么？&quot;（引导学生说出&quot;操作系统&quot;和&quot;应用商店&quot;）</li><li><strong>类比迁移</strong>：手机APP运行在iOS/Android上，工业APP运行在工业互联网平台上——逻辑完全一样</li><li><strong>引出主题</strong>：但工业APP不是手机APP的简单翻版，它有几处本质不同</li></ol><h4 id="知识讲解-25分钟" tabindex="-1">知识讲解（25分钟） <a class="header-anchor" href="#知识讲解-25分钟" aria-label="Permalink to &quot;知识讲解（25分钟）&quot;">​</a></h4><ol><li><strong>手机APP→工业APP的类比</strong>：用教材中的&quot;应用商店&quot;类比，强调&quot;面向平台标准接口编程、从应用市场下载使用&quot;</li><li><strong>工业APP的本质不同</strong>： <ul><li>用户不同：操作工、维修工程师、车间主任 vs 普通消费者</li><li>连接对象不同：PLC、传感器、数据库 vs 社交网络</li><li>出错后果不同：产线停机、安全事故 vs 闪退重开</li></ul></li><li><strong>播放视频</strong>：IIoT-V6-01 工业APP：从大软件到小应用（8分钟）</li></ol><h4 id="回顾讨论-10分钟" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>提问：&quot;如果一个工业APP崩溃了，最坏后果可能是什么？&quot;（引导学生理解工业APP的可靠性要求远高于消费APP）</li><li>提问：&quot;你们觉得工业APP应该部署在云端还是边缘？为什么？&quot;（为6.2节&quot;边缘部署&quot;埋伏笔）</li></ul><h4 id="常见q-a" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>回答要点</th></tr></thead><tbody><tr><td>工业APP和手机APP到底有什么区别？</td><td>核心逻辑相同（都运行在平台上、从应用商店下载），但用户、连接对象、出错后果完全不同</td></tr><tr><td>工业APP只能部署在云端吗？</td><td>不是，车间现场的触摸屏看板就是部署在边缘网关上的工业APP，断网时仍可本地监控</td></tr></tbody></table><hr><h3 id="_6-2-工业app-小而精的工业软件-理论" tabindex="-1">6.2 工业APP：小而精的工业软件（理论） <a class="header-anchor" href="#_6-2-工业app-小而精的工业软件-理论" aria-label="Permalink to &quot;6.2 工业APP：小而精的工业软件（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟-1" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-1" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>对比展示</strong>：展示MES系统界面（复杂、功能多、菜单层级深）vs 一个OEE看板APP界面（简洁、聚焦一个指标）</li><li><strong>提问</strong>：&quot;如果你是一个车间主任，你更愿意用哪个？为什么？&quot;（引导学生说出&quot;简单、直接、解决一个问题&quot;）</li><li><strong>引出核心概念</strong>：&quot;小而精&quot; vs &quot;大而全&quot;</li></ol><h4 id="知识讲解-40分钟" tabindex="-1">知识讲解（40分钟） <a class="header-anchor" href="#知识讲解-40分钟" aria-label="Permalink to &quot;知识讲解（40分钟）&quot;">​</a></h4><ol><li><strong>工业APP的正式定义</strong>：基于工业互联网平台开发的、面向特定工业场景、解决特定工业问题的轻量化应用程序（引用AII白皮书）</li><li><strong>对比表精讲</strong>：逐行讲解教材中的&quot;工业APP vs 传统工业软件&quot;对比表，重点强调： <ul><li>功能范围：大而全 vs 小而精——&quot;一个APP只解决一个问题&quot;</li><li>部署周期：月/年 vs 天/小时——&quot;今天发现问题今天修复&quot;</li><li>开发门槛：专业团队 vs 低代码/无代码——&quot;工程师也能做&quot;</li></ul></li><li><strong>五类工业APP详解</strong>（每类举一个具体例子）： <ul><li>设备监控类：空压机排气压力+温度看板</li><li>分析诊断类：产线质量不良率趋势分析</li><li>预测预警类：轴承振动趋势→剩余使用寿命预测</li><li>操作辅助类：数控机床换模SOP分步指引</li><li>管理决策类：全厂OEE日报、分车间能耗月报</li></ul></li><li><strong>本章定位</strong>：我们要开发的是设备监控类APP——产线设备实时监控看板</li><li><strong>边缘部署</strong>：工业APP不一定只在云端——车间触摸屏看板就是边缘侧的工业APP，和第5章&quot;边缘管现在&quot;一脉相承</li><li><strong>课程思政</strong>：工匠精神——工业APP除了漂亮，还要准确、可靠、安全</li></ol><h4 id="小组讨论-15分钟" tabindex="-1">小组讨论（15分钟） <a class="header-anchor" href="#小组讨论-15分钟" aria-label="Permalink to &quot;小组讨论（15分钟）&quot;">​</a></h4><ul><li>讨论题1：&quot;如果把你学校的食堂管理系统拆成多个小而精的工业APP，可以有哪些？&quot;（每个小组想3个）</li><li>讨论题2：&quot;五类工业APP中，哪一类和第4章做的边缘阈值判断最相关？&quot;（引导到预测预警类或设备监控类）</li><li>请2-3组分享</li></ul><h4 id="回顾讨论-10分钟-1" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-1" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>教材中的三个回顾反思题，请学生口头回答</li><li>重点讨论：&quot;工业APP也可以部署在边缘网关上&quot;和第5章&quot;边缘管现在&quot;的关系</li></ul><h4 id="常见q-a-1" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-1" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>回答要点</th></tr></thead><tbody><tr><td>工业APP是不是就是手机APP的工业版？</td><td>不是。逻辑相同但本质不同：用户、连接对象、出错后果都不同</td></tr><tr><td>&quot;小而精&quot;是不是意味着功能少、没用？</td><td>不是。小而精是聚焦一个具体问题，做到极致；大而全是覆盖整个业务域，但每个功能都不够深入</td></tr><tr><td>五类APP的边界清晰吗？实际中会重叠吗？</td><td>会重叠。一个设备预警APP可能同时属于&quot;监控类&quot;和&quot;预测预警类&quot;，分类是为了理解，不是硬边界</td></tr><tr><td>工业APP部署在边缘和云端有什么区别？</td><td>边缘部署响应快、断网可用，但算力有限；云端部署算力强、可跨厂区，但依赖网络。两者互补</td></tr></tbody></table><hr><h3 id="_6-3-低代码-用积木搭应用-理论" tabindex="-1">6.3 低代码：用积木搭应用（理论） <a class="header-anchor" href="#_6-3-低代码-用积木搭应用-理论" aria-label="Permalink to &quot;6.3 低代码：用积木搭应用（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟-2" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-2" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>提问</strong>：&quot;工厂里的设备和工艺工程师不一定是程序员，但他们最了解业务需求。怎么让他们也能做工业APP？&quot;</li><li><strong>类比</strong>：乐高积木——你不需要会注塑成型，但你能用积木搭出各种造型</li><li><strong>引出主题</strong>：低代码开发——把常见功能抽象成&quot;积木块&quot;</li></ol><h4 id="知识讲解-35分钟" tabindex="-1">知识讲解（35分钟） <a class="header-anchor" href="#知识讲解-35分钟" aria-label="Permalink to &quot;知识讲解（35分钟）&quot;">​</a></h4><ol><li><strong>传统开发 vs 低代码开发</strong>： <ul><li>传统：需求文档→UI设计→前端代码→后端接口→测试→部署，至少3种专业角色、数周时间</li><li>低代码：拖积木→连线→配置→部署，1种角色、数小时</li></ul></li><li><strong>低代码的&quot;低&quot;到底低在哪里</strong>：低在&quot;从零写代码&quot;的比例降低了。80%常见需求拖拽完成，20%特殊逻辑手写代码。低代码不排斥写代码</li><li><strong>无代码（No-Code）</strong>：低代码的极致简化形态，配置复杂度降为零，开箱即用的模板</li><li><strong>公民开发者（Citizen Developer）</strong>： <ul><li>Gartner提出的概念：业务人员使用IT不禁止的工具创建应用</li><li>Gartner预测：到2026年大型企业中公民开发者数量将是专业开发者的4倍</li><li>对工业互联网的意义：让最懂业务的人参与应用开发</li></ul></li><li><strong>回到Node-RED</strong>：Node-RED本身就是低代码工具——第3章拖Modbus Read节点、第4章拖Switch节点，都是&quot;搭积木&quot;。Function节点是&quot;后门&quot;——低代码不排斥写代码</li><li><strong>本章新增积木</strong>：Dashboard节点——Gauge、Chart、Button、Text、Notification、LED</li><li><strong>播放视频</strong>：IIoT-V6-02 低代码开发与公民开发者（6分钟）</li></ol><h4 id="回顾讨论-10分钟-2" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-2" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>提问：&quot;低代码的&#39;低&#39;是低在哪里？是不是意味着完全不用写代码？&quot;（强调：不是，80%拖拽+20%手写）</li><li>提问：&quot;你在前几章用Node-RED拖拽节点时，哪些是&#39;搭积木&#39;，哪些必须写Function节点？&quot;（帮助学生建立直观认识）</li><li>提问：&quot;&#39;公民开发者&#39;对工业互联网推广有什么意义？&quot;（让最懂工艺的人参与开发，缩短需求到实现的距离）</li></ul><h4 id="常见q-a-2" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-2" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>回答要点</th></tr></thead><tbody><tr><td>低代码开发出来的APP质量会不会比手写代码差？</td><td>不一定。低代码平台封装了最佳实践，常见功能反而更稳定；特殊逻辑仍可手写，质量不受限</td></tr><tr><td>公民开发者会不会抢程序员的饭碗？</td><td>不会。公民开发者解决的是长尾需求（小而精的APP），复杂系统仍需专业开发者。两者互补</td></tr><tr><td>Node-RED算低代码还是无代码？</td><td>算低代码。大部分操作拖拽完成，但Function节点需要写JavaScript，所以不是纯无代码</td></tr><tr><td>Function节点是不是说明低代码&quot;不够用&quot;？</td><td>恰恰相反。Function节点是低代码的&quot;安全阀&quot;——80%用积木，20%用代码，两者结合才是低代码的完整形态</td></tr></tbody></table><hr><h3 id="_6-4-动手实践-dashboard节点逐一上手-实践" tabindex="-1">6.4 动手实践：Dashboard节点逐一上手（实践） <a class="header-anchor" href="#_6-4-动手实践-dashboard节点逐一上手-实践" aria-label="Permalink to &quot;6.4 动手实践：Dashboard节点逐一上手（实践）&quot;">​</a></h3><blockquote><p>⚠️ <strong>教师特别注意</strong>：<code>node-red-dashboard</code> 插件已于2024年6月标记为 <strong>deprecated（已弃用）</strong>，推荐替代方案为 <code>@flowfuse/node-red-dashboard</code>。两者界面和用法基本一致。教学时请提醒学生：如果搜索 <code>node-red-dashboard</code> 找不到，改搜 <code>@flowfuse/node-red-dashboard</code>。建议教师提前在自己的环境中测试两个包的可用性。</p></blockquote><h4 id="教学导入-5分钟" tabindex="-1">教学导入（5分钟） <a class="header-anchor" href="#教学导入-5分钟" aria-label="Permalink to &quot;教学导入（5分钟）&quot;">​</a></h4><ol><li>回顾6.3节：&quot;低代码就是搭积木——现在我们来认识这些积木长什么样&quot;</li><li>展示一个做好的Dashboard效果截图，激发兴趣</li></ol><h4 id="任务一-安装dashboard插件-15分钟" tabindex="-1">任务一：安装Dashboard插件（15分钟） <a class="header-anchor" href="#任务一-安装dashboard插件-15分钟" aria-label="Permalink to &quot;任务一：安装Dashboard插件（15分钟）&quot;">​</a></h4><ol><li><strong>分步演示</strong>：Node-RED菜单 → 节点管理 → 安装标签页 → 搜索 <code>node-red-dashboard</code> → 点击安装</li><li><strong>学生操作</strong>：跟着做，教师巡视</li><li><strong>验证安装</strong>：确认左侧节点面板出现&quot;dashboard&quot;分类</li><li><strong>提醒deprecated问题</strong>：告知学生 <code>node-red-dashboard</code> 已deprecated，推荐 <code>@flowfuse/node-red-dashboard</code></li><li><strong>Docker提醒</strong>：如果使用第5章Docker部署且未配置数据卷（<code>-v</code>），容器删除后插件会丢失</li></ol><blockquote><p><strong>播放视频</strong>：IIoT-V6-03 Dashboard节点安装与常用组件（12分钟）</p></blockquote><h4 id="任务二-六种节点逐一上手-50分钟" tabindex="-1">任务二：六种节点逐一上手（50分钟） <a class="header-anchor" href="#任务二-六种节点逐一上手-50分钟" aria-label="Permalink to &quot;任务二：六种节点逐一上手（50分钟）&quot;">​</a></h4><p>建议每个节点花3-5分钟：教师演示配置要点 → 学生跟着操作 → 部署 → 访问 <code>http://IP:1880/ui</code> 观察效果。</p><p><strong>Gauge（仪表盘）</strong>（8分钟）</p><ul><li>演示：拖出Gauge → 配置最小值/最大值/单位/颜色分段 → 部署</li><li>重点：颜色分段（绿→黄→红）是工业看板的核心设计——让操作员一眼判断</li><li>学生操作：配置一个0-100的温度Gauge，绿0-70、黄70-85、红85-100</li></ul><p><strong>Chart（图表）</strong>（10分钟）</p><ul><li>演示：拖出Chart → 配置折线图/柱状图/X轴时间范围 → 部署</li><li>重点：<code>msg.topic</code> 字段区分多条数据线——这是6.5节综合实践的关键知识点</li><li>学生操作：配置一个折线图，用Inject+Function发送带topic的数据，观察两条线</li></ul><p><strong>Button（按钮）</strong>（5分钟）</p><ul><li>演示：拖出Button → 配置颜色和payload值 → 连到Debug节点 → 部署</li><li>重点：按钮是用户交互的入口，点击后发送的payload可以触发后续逻辑</li></ul><p><strong>Text（文本）</strong>（5分钟）</p><ul><li>演示：拖出Text → 格式栏写 <code>当前温度：\\{\\{msg.payload\\}\\} ℃</code> → 部署</li><li>重点：模板变量 <code>\\{\\{msg.payload\\}\\}</code> 自动替换为实际数据</li></ul><p><strong>Notification（通知）</strong>（7分钟）</p><ul><li>演示：拖出Notification → 配置通知级别（info蓝/warn黄/error红）和显示时长 → 部署</li><li>重点：Notification通常需要配合Switch节点做条件判断——只有超标时才弹出</li><li>预告：6.5节会完整实现&quot;温度&gt;85℃时弹出告警通知&quot;</li></ul><p><strong>LED（指示灯）</strong>（5分钟）</p><ul><li>演示：拖出LED → 配置颜色规则（值&gt;80红、值&gt;70黄、其余绿）→ 部署</li><li>重点：LED是&quot;一眼可知&quot;的设备健康指示，适合放在Dashboard最显眼位置</li></ul><h4 id="任务三-理解dashboard布局系统-15分钟" tabindex="-1">任务三：理解Dashboard布局系统（15分钟） <a class="header-anchor" href="#任务三-理解dashboard布局系统-15分钟" aria-label="Permalink to &quot;任务三：理解Dashboard布局系统（15分钟）&quot;">​</a></h4><ol><li><strong>讲解三级结构</strong>： <ul><li>Tab（标签页）：顶层，如&quot;产线监控&quot;标签页、&quot;历史分析&quot;标签页</li><li>Group（分组）：每个Tab下的卡片，带标题的矩形区域</li><li>Widget（部件）：每个单独的Dashboard节点</li></ul></li><li><strong>演示操作</strong>：在右侧边栏&quot;dashboard&quot;标签页中创建Tab和Group，将节点分配到对应Group</li><li><strong>类比</strong>：Tab≈手机APP的底部导航栏、Group≈页面的卡片区域、Widget≈卡片里的按钮/文字/图片</li><li><strong>学生操作</strong>：创建一个Tab&quot;测试页&quot;，下面建两个Group，把刚才的节点分别放进去</li></ol><h4 id="回顾讨论-10分钟-3" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-3" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>提问：&quot;六种Dashboard节点分别适合什么场景？各举一个工业例子&quot;</li><li>提问：&quot;Tab→Group→Widget三级布局和手机APP的什么概念最相似？&quot;</li><li>提问：&quot;如果要做一个&#39;车间能耗监控&#39;看板，你会怎么设计Tab和Group？&quot;</li></ul><h4 id="常见q-a-3" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-3" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>回答要点</th></tr></thead><tbody><tr><td>安装Dashboard节点时搜索不到怎么办？</td><td><code>node-red-dashboard</code> 已deprecated，可能从npm下架；改搜 <code>@flowfuse/node-red-dashboard</code></td></tr><tr><td>访问/ui页面空白怎么办？</td><td>检查：①是否已部署 ②节点是否配置了Group和Tab ③URL是否正确（<a href="http://IP:1880/ui%EF%BC%89" target="_blank" rel="noreferrer">http://IP:1880/ui）</a></td></tr><tr><td>Gauge的指针不动怎么办？</td><td>检查：①是否有数据流入 ②msg.payload是否为数值类型 ③Gauge的min/max范围是否合理</td></tr><tr><td>Chart上只有点没有线怎么办？</td><td>需要持续发送数据，Chart会自动连线；单次发送只显示一个点</td></tr><tr><td>LED颜色不变怎么办？</td><td>检查颜色规则的顺序（从上到下匹配，先匹配的先生效）和msg.payload的值类型</td></tr><tr><td>Button点击后Debug没输出？</td><td>检查Button是否连到了Debug节点，以及Button的payload配置是否正确</td></tr></tbody></table><hr><h3 id="_6-5-综合实践-开发产线设备监控dashboard-实践" tabindex="-1">6.5 综合实践：开发产线设备监控Dashboard（实践） <a class="header-anchor" href="#_6-5-综合实践-开发产线设备监控dashboard-实践" aria-label="Permalink to &quot;6.5 综合实践：开发产线设备监控Dashboard（实践）&quot;">​</a></h3><h4 id="教学导入-10分钟-3" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-3" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ol><li><strong>回顾串联</strong>：&quot;从第3章的Modbus数据采集到第4章的边缘处理，从第5章的平台管理到今天——我们终于到了&#39;最后一公里&#39;&quot;</li><li><strong>展示目标</strong>：展示完整Dashboard最终效果截图，让学生有清晰的目标</li><li><strong>说明定位</strong>：本章做的是简化版工业APP原型（数据源本地模拟、界面是Web看板），但核心逻辑和真实平台工业APP完全一致</li></ol><blockquote><p><strong>播放视频</strong>：IIoT-V6-04 开发产线设备监控看板（15分钟）</p></blockquote><h4 id="任务一-创建布局-10分钟" tabindex="-1">任务一：创建布局（10分钟） <a class="header-anchor" href="#任务一-创建布局-10分钟" aria-label="Permalink to &quot;任务一：创建布局（10分钟）&quot;">​</a></h4><ol><li><strong>演示</strong>：在右侧&quot;dashboard&quot;标签页创建Tab&quot;产线监控&quot;，下面创建四个Group</li><li><strong>学生操作</strong>：跟着创建</li><li><strong>教师巡视</strong>：确认每个学生都创建了正确的Tab和Group结构</li></ol><h4 id="任务二-搭建仪表盘——温度-振动-25分钟" tabindex="-1">任务二：搭建仪表盘——温度+振动（25分钟） <a class="header-anchor" href="#任务二-搭建仪表盘——温度-振动-25分钟" aria-label="Permalink to &quot;任务二：搭建仪表盘——温度+振动（25分钟）&quot;">​</a></h4><ol><li><strong>确认数据源</strong>：确保Flow上有第4章的&quot;电机传感器模拟&quot;Function节点（如果已删，重新创建Inject+Function）</li><li><strong>分步演示</strong>： <ul><li>拖两个Gauge节点，分别配置温度和振动</li><li>拖两个Change节点，提取temperature和vibration字段</li><li>连线：传感器模拟Function → Change → Gauge</li></ul></li><li><strong>重点讲解</strong>：Change节点的&quot;Set&quot;操作——<code>msg.payload</code> 设为 <code>msg.payload.temperature</code></li><li><strong>学生操作</strong>：部署后观察两个仪表盘指针摆动</li></ol><h4 id="任务三-搭建趋势图-20分钟" tabindex="-1">任务三：搭建趋势图（20分钟） <a class="header-anchor" href="#任务三-搭建趋势图-20分钟" aria-label="Permalink to &quot;任务三：搭建趋势图（20分钟）&quot;">​</a></h4><ol><li><strong>重点讲解</strong>：多输出Function节点——底部&quot;输出&quot;数量从1改为2</li><li><strong>代码讲解</strong>：<div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tempMsg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { payload: msg.payload.temperature, topic: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;温度&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vibMsg  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { payload: msg.payload.vibration,  topic: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;振动&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [tempMsg, vibMsg];</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><strong>关键概念</strong>：<code>msg.topic</code> 字段让Chart区分不同数据线——&quot;温度&quot;画一条线，&quot;振动&quot;画另一条</li><li><strong>连线讲解</strong>：两条输出线都连到同一个Chart节点</li><li><strong>学生操作</strong>：部署后观察两条曲线</li></ol><h4 id="任务四-搭建指示灯和文本显示-20分钟" tabindex="-1">任务四：搭建指示灯和文本显示（20分钟） <a class="header-anchor" href="#任务四-搭建指示灯和文本显示-20分钟" aria-label="Permalink to &quot;任务四：搭建指示灯和文本显示（20分钟）&quot;">​</a></h4><ol><li><strong>LED配置</strong>：Value format设为 <code>\\{\\{msg.payload\\}\\}</code>，添加三条颜色规则（&gt;80红、&gt;70黄、其余绿）</li><li><strong>Text配置</strong>：格式栏使用模板变量 <code>最新温度：\\{\\{msg.payload\\}\\} ℃</code></li><li><strong>Button配置</strong>：点击时发送 <code>{payload: &quot;ack&quot;}</code> 到Debug节点</li><li><strong>Notification配置</strong>： <ul><li>先加Switch节点做条件判断：<code>msg.payload &gt; 85</code> 时才放行</li><li>再连Notification节点：级别选&quot;warning&quot;，显示5秒</li></ul></li><li><strong>学生操作</strong>：逐一配置，部署测试</li></ol><h4 id="任务五-整体联调-15分钟" tabindex="-1">任务五：整体联调（15分钟） <a class="header-anchor" href="#任务五-整体联调-15分钟" aria-label="Permalink to &quot;任务五：整体联调（15分钟）&quot;">​</a></h4><ol><li><strong>对照连线总览检查</strong>：将教材中的连线总览图投影到屏幕上，让学生对照检查<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Inject(1s)] → [传感器模拟Function] ─┬─→ [Change:提取温度] ─┬─→ [Gauge:温度]</span></span>
<span class="line"><span>                                      │                      ├─→ [LED]</span></span>
<span class="line"><span>                                      │                      └─→ [Switch(&gt;85)] → [Notification]</span></span>
<span class="line"><span>                                      │</span></span>
<span class="line"><span>                                      └─→ [Change:提取振动] ───→ [Gauge:振动]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[传感器模拟Function] → [拆分Function(2输出)] ─┬─→ [Chart:温度线]</span></span>
<span class="line"><span>                                                 └─→ [Chart:振动线]</span></span>
<span class="line"><span>                                                 （或两条输出都连到同一个Chart）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Change:提取温度] → [Text:温度读数]</span></span>
<span class="line"><span>[Change:提取振动] → [Text:振动读数]</span></span>
<span class="line"><span>[Button:确认报警] → [Debug]</span></span>
<span class="line"><span>[Button:查看详情] → [Debug]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div></li><li><strong>部署运行</strong>：让系统运行几分钟，观察Dashboard上的变化</li><li><strong>验证要点</strong>： <ul><li>Gauge指针在随机波动中持续摆动，温度超80℃时颜色从黄跳红</li><li>LED同步变色</li><li>Chart上两条曲线持续向右延伸</li><li>点击&quot;确认报警&quot;按钮，Debug面板收到 <code>{payload: &quot;ack&quot;}</code></li><li>温度超85℃时，右上角弹出黄色告警通知</li></ul></li></ol><h4 id="工业app安全讲解-5分钟" tabindex="-1">工业APP安全讲解（5分钟） <a class="header-anchor" href="#工业app安全讲解-5分钟" aria-label="Permalink to &quot;工业APP安全讲解（5分钟）&quot;">​</a></h4><ul><li>简要讲解四条安全底线：访问控制、数据加密、权限管理、日志审计</li><li>强调：本章是原型开发，不实现安全功能，但实际项目中这些是必须的</li></ul><h4 id="回顾讨论-10分钟-4" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟-4" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><ul><li>提问：&quot;从第3章的Modbus传感器模拟到今天Dashboard上的仪表盘指针摆动，数据经历了哪些&#39;站&#39;？&quot;</li><li>提问：&quot;你做的Dashboard和真实的工业APP有哪些差距？&quot;</li><li>提问：&quot;如果要给Dashboard加上&#39;温度超标时自动弹出通知&#39;的功能，你会用哪个节点？怎么连？&quot;（实际上任务四已经实现了，可以让学生回顾实现过程）</li></ul><h4 id="常见q-a-4" tabindex="-1">常见Q&amp;A <a class="header-anchor" href="#常见q-a-4" aria-label="Permalink to &quot;常见Q&amp;A&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>回答要点</th></tr></thead><tbody><tr><td>传感器模拟Function节点删了怎么办？</td><td>重新拖Inject节点（1秒间隔）+ Function节点，代码参考第4章4.5节任务一</td></tr><tr><td>Change节点提取字段后Gauge显示NaN</td><td>msg.payload可能不是数值类型，在Change节点后加一个Function节点做 <code>msg.payload = Number(msg.payload)</code></td></tr><tr><td>Chart上两条线颜色一样分不开</td><td>确保两条数据线的 <code>msg.topic</code> 不同（如&quot;温度&quot;和&quot;振动&quot;），Chart会自动分配不同颜色</td></tr><tr><td>多输出Function节点怎么连线？</td><td>双击Function节点，底部&quot;输出&quot;数量改为2，保存后节点右侧出现两个输出端口，分别拖线</td></tr><tr><td>LED一直绿色不变色</td><td>检查：①LED的Value format是否为 <code>\\{\\{msg.payload\\}\\}</code> ②颜色规则是否正确 ③传入的值是否为数值类型</td></tr><tr><td>Notification一直弹出不停</td><td>Switch节点的条件判断可能有问题，或者数据源发送频率太高。可以在Switch后加一个delay节点限流</td></tr><tr><td>部署后Dashboard页面没变化</td><td>尝试刷新浏览器（Ctrl+F5强制刷新），清除缓存</td></tr></tbody></table><hr><h2 id="四、教学评价建议" tabindex="-1">四、教学评价建议 <a class="header-anchor" href="#四、教学评价建议" aria-label="Permalink to &quot;四、教学评价建议&quot;">​</a></h2><h3 id="过程性评价" tabindex="-1">过程性评价 <a class="header-anchor" href="#过程性评价" aria-label="Permalink to &quot;过程性评价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价维度</th><th>评价项</th><th>评分标准</th><th>自评(30%)</th><th>互评(30%)</th><th>师评(40%)</th></tr></thead><tbody><tr><td>操作规范</td><td>Dashboard节点安装成功</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>结果正确</td><td>仪表盘正常显示温度</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>原理理解</td><td>能说出六种Dashboard节点的用途</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>原理理解</td><td>能解释Tab→Group→Widget三级布局</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>创新意识</td><td>尝试了不同的仪表盘样式和颜色分段</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>合作沟通</td><td>能帮助同学安装节点</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr></tbody></table><h3 id="终结性评价-6-5综合实践" tabindex="-1">终结性评价（6.5综合实践） <a class="header-anchor" href="#终结性评价-6-5综合实践" aria-label="Permalink to &quot;终结性评价（6.5综合实践）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价维度</th><th>评价项</th><th>评分标准</th><th>自评(30%)</th><th>互评(30%)</th><th>师评(40%)</th></tr></thead><tbody><tr><td>功能完整性</td><td>温度仪表盘、图表、LED、文本都正常</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>界面可用性</td><td>布局合理、配色清晰、一眼看懂</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>数据准确性</td><td>数据显示正确、异常判断准确</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>创新拓展</td><td>完成了振动监控或其他额外功能</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr><tr><td>合作沟通</td><td>能帮助同学解决问题</td><td>5-4-3-2-1</td><td></td><td></td><td></td></tr></tbody></table><h3 id="评价建议" tabindex="-1">评价建议 <a class="header-anchor" href="#评价建议" aria-label="Permalink to &quot;评价建议&quot;">​</a></h3><ol><li><strong>6.4节评价</strong>侧重&quot;逐一上手&quot;的过程——每个学生都应该亲手配置过六种节点，不能只看不做</li><li><strong>6.5节评价</strong>侧重&quot;完整链路&quot;——能从数据源到界面端到端跑通，比单个组件漂亮更重要</li><li><strong>创新加分</strong>：鼓励学有余力的学生添加额外功能（如振动监控、报警声音、多设备切换等），可作为加分项</li><li><strong>过程记录</strong>：要求学生填写工作手册任务单，记录操作步骤和遇到的问题</li></ol><hr><h2 id="五、思政融入设计说明" tabindex="-1">五、思政融入设计说明 <a class="header-anchor" href="#五、思政融入设计说明" aria-label="Permalink to &quot;五、思政融入设计说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>融入点</th><th>结合内容</th><th>教学方法</th><th>预期效果</th></tr></thead><tbody><tr><td><strong>工匠精神</strong></td><td>6.2课程思政：工业APP的准确、可靠、安全；6.5看板设计细节（数据准确、布局合理、配色清晰）</td><td>案例对比（好看板vs坏看板）+ 实践要求</td><td>培养学生注重细节、追求完美的态度</td></tr><tr><td><strong>用户导向思维</strong></td><td>6.2五类APP设计；6.5从工人角度设计看板（一眼看懂、操作简单）</td><td>角色代入（假如你是车间操作工）</td><td>培养学生从用户需求出发的思维</td></tr><tr><td><strong>工程师伦理</strong></td><td>6.5工业APP安全：访问控制、数据加密、权限管理、日志审计</td><td>案例讨论（数据错误导致事故）</td><td>培养学生的责任感和严谨态度</td></tr><tr><td><strong>创新思维</strong></td><td>6.3公民开发者理念；6.5鼓励学生添加额外功能</td><td>头脑风暴 + 可选挑战</td><td>培养学生的创新意识和探索精神</td></tr></tbody></table><hr><h2 id="六、思考与练习参考答案" tabindex="-1">六、思考与练习参考答案 <a class="header-anchor" href="#六、思考与练习参考答案" aria-label="Permalink to &quot;六、思考与练习参考答案&quot;">​</a></h2><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><ol><li><strong>C</strong>（小而精、快速迭代是工业APP最突出的特征，A是大而全的特点，B是传统工业软件的特点，D与低代码理念矛盾）</li><li><strong>C</strong>（Dashboard插件用于创建用户界面和数据可视化）</li><li><strong>B</strong>（<code>msg.topic</code> 字段用于区分Chart中的不同数据线，不同topic画不同颜色的线）</li><li><strong>D</strong>（Tab → Group → Widget，从上到下的三级结构）</li><li><strong>C</strong>（Function节点是低代码的&quot;后门&quot;，用于现有积木无法直接实现的逻辑）</li><li><strong>B</strong>（颜色分段的核心目的是帮助操作员快速判断设备状态，不是单纯美化）</li></ol><h3 id="判断题" tabindex="-1">判断题 <a class="header-anchor" href="#判断题" aria-label="Permalink to &quot;判断题&quot;">​</a></h3><ol><li><strong>×</strong>（工业APP可以用低代码/无代码工具开发，工程师也能参与，这正是&quot;公民开发者&quot;的意义）</li><li><strong>√</strong>（MES和ERP是传统工业软件&quot;大而全&quot;的典型代表）</li><li><strong>×</strong>（低代码不排斥写代码，80%常见需求拖拽完成，20%特殊逻辑手写代码）</li><li><strong>√</strong>（Notification节点可以像手机通知栏一样弹出提示消息，支持info/warn/error三种级别）</li><li><strong>×</strong>（Gauge可以显示小数，值格式 <code>{{value}}</code> 支持任意数值）</li><li><strong>×</strong>（一个Chart节点可以通过 <code>msg.topic</code> 字段区分多条数据线，同时显示多条曲线）</li><li><strong>√</strong>（本章Dashboard的数据源可以复用第4章的电机传感器模拟Function节点）</li></ol><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p><strong>把MES拆成多个工业APP</strong>（参考答案）：</p><ul><li>OEE看板APP：实时显示设备综合效率，解决&quot;设备利用率低但不自知&quot;的问题</li><li>换模指引APP：为操作员提供标准化的换模SOP分步指引，解决&quot;换模时间长、操作不规范&quot;的问题</li><li>质量追溯APP：扫码查询产品的全工序加工记录，解决&quot;质量异常时找不到原因&quot;的问题</li><li>其他合理答案均可</li></ul></li><li><p><strong>低代码的&quot;边界&quot;</strong>（参考答案）：</p><ul><li>拖拽能完成：Gauge配置、Chart配置、Button配置、Change节点字段提取、Switch节点条件判断、LED颜色规则</li><li>必须写代码：传感器数据模拟（Function节点）、Chart多线输出的数据拆分（Function节点）</li><li>边界：当现有积木节点的配置选项无法满足需求时，就需要写代码。低代码的&quot;边界&quot;就是&quot;积木能拼到什么程度&quot;</li></ul></li><li><p><strong>Dashboard用户体验改进</strong>（参考答案，学生答案合理即可）：</p><ul><li>添加报警声音提示：温度超标时除了视觉告警，还应有声音提醒</li><li>添加历史数据查询：当前只能看实时和5分钟趋势，应支持查看更长时间范围</li><li>添加设备切换功能：当前只监控一台电机，应支持切换查看不同设备</li><li>响应式布局：当前Dashboard在手机上显示效果差，应优化移动端适配</li><li>数据单位标注更清晰</li></ul></li><li><p><strong>从第3章到第6章的完整数据链路</strong>（参考答案）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第3章：Modbus Read → PLC/传感器（数据采集）</span></span>
<span class="line"><span>第4章：Function节点 → Switch节点（边缘处理：数据解析+阈值判断）</span></span>
<span class="line"><span>第5章：MQTT节点 → 工业互联网平台（数据上传+平台管理）</span></span>
<span class="line"><span>第6章：Change节点 → Gauge/Chart/LED/Text（界面呈现）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>数据经历了&quot;采集→处理→传输→呈现&quot;四个&quot;站&quot;，每一站对应一章。</p></li></ol><hr><h2 id="七、教学反思要点" tabindex="-1">七、教学反思要点 <a class="header-anchor" href="#七、教学反思要点" aria-label="Permalink to &quot;七、教学反思要点&quot;">​</a></h2><p>课后请思考并记录：</p><ol><li>学生对&quot;小而精 vs 大而全&quot;的理解是否到位？能否举出自己的例子？</li><li>五类工业APP的分类学生是否清晰？能否区分&quot;监控&quot;和&quot;预测&quot;的区别？</li><li>低代码和公民开发者的概念学生是否理解？有没有觉得&quot;低代码=不专业&quot;的误解？</li><li>六种Dashboard节点的逐一上手环节，时间是否够用？哪种节点学生配置最困难？</li><li>多输出Function节点对学生来说难吗？需要更详细的讲解吗？</li><li>连线总览图对学生排查问题有帮助吗？是否需要提供可打印版本？</li><li>Dashboard节点安装成功率高吗？deprecated问题是否影响了教学？</li><li>学生的看板设计注重细节吗？还是只追求花哨？</li><li>可选挑战任务完成情况如何？需要调整难度吗？</li></ol><hr><h2 id="八、教学资源清单" tabindex="-1">八、教学资源清单 <a class="header-anchor" href="#八、教学资源清单" aria-label="Permalink to &quot;八、教学资源清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源类型</th><th>资源名称</th><th>时长/大小</th><th>备注</th></tr></thead><tbody><tr><td>微课视频</td><td>IIoT-V6-01 工业APP：从大软件到小应用</td><td>8分钟</td><td>配套6.1-6.2节</td></tr><tr><td>微课视频</td><td>IIoT-V6-02 低代码开发与公民开发者</td><td>6分钟</td><td>配套6.3节</td></tr><tr><td>操作演示视频</td><td>IIoT-V6-03 Dashboard节点安装与常用组件</td><td>12分钟</td><td>配套6.4节</td></tr><tr><td>操作演示视频</td><td>IIoT-V6-04 开发产线设备监控看板</td><td>15分钟</td><td>配套6.5节</td></tr><tr><td>示例Flow</td><td>第6章 产线监控看板示例Flow JSON</td><td>几KB</td><td>可导入Node-RED直接使用</td></tr><tr><td>拓展案例</td><td>卡奥斯APPStore上的实际工业APP截图</td><td>—</td><td><a href="https://www.cosmoplat.com/appstore/" target="_blank" rel="noreferrer">https://www.cosmoplat.com/appstore/</a></td></tr><tr><td>参考文档</td><td>工业互联网产业联盟《工业互联网APP白皮书》</td><td>—</td><td>提供PDF下载链接</td></tr><tr><td>参考文档</td><td>Node-RED Dashboard官方文档</td><td>—</td><td><a href="https://flows.nodered.org/node/node-red-dashboard" target="_blank" rel="noreferrer">https://flows.nodered.org/node/node-red-dashboard</a></td></tr><tr><td>参考文档</td><td>@flowfuse/node-red-dashboard文档</td><td>—</td><td>推荐替代方案文档</td></tr></tbody></table><hr><h2 id="九、学生常见错误预判" tabindex="-1">九、学生常见错误预判 <a class="header-anchor" href="#九、学生常见错误预判" aria-label="Permalink to &quot;九、学生常见错误预判&quot;">​</a></h2><ol><li><p><strong>Dashboard节点安装失败</strong></p><ul><li>原因：网络问题、npm源慢、<code>node-red-dashboard</code> 已deprecated可能搜不到</li><li>解决方案：提前准备国内npm源（如淘宝源），或者改搜 <code>@flowfuse/node-red-dashboard</code>，或者提前把节点安装到Docker镜像里</li></ul></li><li><p><strong>访问/ui看不到看板</strong></p><ul><li>原因：节点没部署、节点没配置Group或Tab、URL错了</li><li>解决方案：检查部署状态、检查节点配置中的Group分配、确认URL是 <code>http://&lt;IP&gt;:1880/ui</code></li></ul></li><li><p><strong>Function节点的多个输出不会连</strong></p><ul><li>原因：不知道Function可以有多个输出</li><li>解决方案：演示如何在Function节点配置里增加输出端口（底部&quot;输出&quot;数量，默认1个，改为2）</li></ul></li><li><p><strong>Gauge显示NaN或不更新</strong></p><ul><li>原因：msg.payload不是数值类型（可能是对象或字符串）</li><li>解决方案：在Gauge前加Change节点提取数值字段，或加Function节点做 <code>msg.payload = Number(msg.payload)</code></li></ul></li><li><p><strong>Chart上只有点没有线/两条线颜色一样</strong></p><ul><li>原因：数据发送频率太低只显示点；两条线的 <code>msg.topic</code> 相同导致颜色一样</li><li>解决方案：确保Inject间隔为1秒持续发送；确保温度和振动的topic不同</li></ul></li><li><p><strong>LED颜色不变色</strong></p><ul><li>原因：Value format没设为 <code>\\{\\{msg.payload\\}\\}</code>、颜色规则顺序错误、传入值不是数值类型</li><li>解决方案：检查Value format、调整颜色规则顺序（大的阈值在前）、确保传入数值</li></ul></li><li><p><strong>Notification一直弹出不停</strong></p><ul><li>原因：没有用Switch节点做条件判断，每条数据都触发通知</li><li>解决方案：在Notification前加Switch节点，设置 <code>msg.payload &gt; 85</code> 条件</li></ul></li><li><p><strong>看板布局混乱</strong></p><ul><li>原因：没有合理使用Group分组，或者Widget的Size设置不合理</li><li>解决方案：强制要求学生按教材的四个Group分区，引导合理设置Widget尺寸</li></ul></li><li><p><strong>Docker环境插件丢失</strong></p><ul><li>原因：Docker容器未配置数据卷（<code>-v</code>），容器重启后插件丢失</li><li>解决方案：提醒学生使用 <code>-v</code> 挂载数据目录，或每次重启后重新安装</li></ul></li></ol><hr><p><strong>下一步</strong>：准备第6章的示例Flow JSON文件，方便导入；收集好的工业看板截图作为案例；提前测试 <code>@flowfuse/node-red-dashboard</code> 的兼容性。</p>`,126)])])}const g=a(r,[["render",d]]);export{p as __pageData,g as default};
